import{_ as e,c as t,o as i,a0 as n}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"nl/blog/inner-critic.md","filePath":"nl/blog/inner-critic.md"}');const a=e({name:"nl/blog/inner-critic.md"},[["render",function(e,r,a,o,l,s){return i(),t("div",null,[...r[0]||(r[0]=[n('<h1 id="het-begrijpen-van-de-innerlijke-criticus" tabindex="-1">Het begrijpen van de innerlijke criticus <a class="header-anchor" href="#het-begrijpen-van-de-innerlijke-criticus" aria-label="Permalink to &quot;Het begrijpen van de innerlijke criticus&quot;">​</a></h1><p>Iedere pétanque-speler kent dat stemmetje. Dat stemmetje dat fluistert &quot;je gaat missen&quot; net voordat je gooit. Dat stemmetje dat je laatste mislukte worp eindeloos herhaalt. Dit is je innerlijke criticus – en leren ermee om te gaan is essentieel voor topprestaties.</p><h2 id="wat-is-de-innerlijke-criticus" tabindex="-1">Wat is de innerlijke criticus? <a class="header-anchor" href="#wat-is-de-innerlijke-criticus" aria-label="Permalink to &quot;Wat is de innerlijke criticus?&quot;">​</a></h2><p>De innerlijke criticus is die stem in jezelf die oordeelt, kritiek levert en je zelfvertrouwen ondermijnt. Bij pétanque duikt deze stem vaak op de meest ongelegen momenten op:</p><ul><li><strong>Vlak voor een cruciaal schot</strong>: &quot;Iedereen kijkt toe. Verknoei dit niet.&quot;</li><li><strong>Na een misser</strong>: &quot;Je bezwijkt altijd onder druk.&quot;</li><li><strong>Tijdens een verliesreeks:</strong> &quot;Je bent niet goed genoeg voor dit niveau.&quot;</li></ul><p>Deze stem probeert je niet te kwetsen; het is eigenlijk een misplaatste poging tot bescherming. Je hersenen proberen je voor te bereiden op een mislukking, zodat die minder pijn doet. Maar deze &#39;bescherming&#39; verandert in zelfsabotage.</p><h2 id="je-eigen-patronen-herkennen" tabindex="-1">Je eigen patronen herkennen <a class="header-anchor" href="#je-eigen-patronen-herkennen" aria-label="Permalink to &quot;Je eigen patronen herkennen&quot;">​</a></h2><p>De eerste stap is bewustwording. Begin op te merken wanneer je innerlijke criticus opduikt:</p><h3 id="veelvoorkomende-triggers" tabindex="-1">Veelvoorkomende triggers <a class="header-anchor" href="#veelvoorkomende-triggers" aria-label="Permalink to &quot;Veelvoorkomende triggers&quot;">​</a></h3><ul><li>Situaties onder hoge druk (matchpoint, belangrijke toernooien)</li><li>Na een fout te hebben gemaakt</li><li>Wanneer tegenstanders goed presteren</li><li>Wanneer teamgenoten gefrustreerd lijken</li><li>Lichamelijke vermoeidheid of ongemak</li></ul><h3 id="algemene-berichten" tabindex="-1">Algemene berichten <a class="header-anchor" href="#algemene-berichten" aria-label="Permalink to &quot;Algemene berichten&quot;">​</a></h3><ul><li>&quot;Je kunt niet tegen druk.&quot;</li><li>&quot;Jij bent niet zo goed als zij.&quot;</li><li>&quot;Iedereen oordeelt over je&quot;</li><li>&quot;Je faalt altijd wanneer het erop aankomt.&quot;</li></ul><h2 id="de-impact-op-de-prestaties" tabindex="-1">De impact op de prestaties <a class="header-anchor" href="#de-impact-op-de-prestaties" aria-label="Permalink to &quot;De impact op de prestaties&quot;">​</a></h2><p>Wanneer je innerlijke criticus de overhand neemt, reageert je lichaam als volgt:</p><ol><li><strong>Spierspanning neemt toe</strong> — Je worp wordt stijver.</li><li><strong>De ademhaling wordt oppervlakkiger</strong> — Minder zuurstof, minder concentratie</li><li><strong>Zicht vernauwt</strong> — Je verliest het besef van het terrein.</li><li><strong>Besluitvorming lijdt eronder</strong> — Je twijfelt aan jezelf.</li></ol><p>Dit creëert een vicieuze cirkel: de innerlijke criticus leidt tot slechte prestaties, wat de criticus meer munitie geeft.</p><h2 id="strategieen-om-de-innerlijke-criticus-te-beheersen" tabindex="-1">Strategieën om de innerlijke criticus te beheersen <a class="header-anchor" href="#strategieen-om-de-innerlijke-criticus-te-beheersen" aria-label="Permalink to &quot;Strategieën om de innerlijke criticus te beheersen&quot;">​</a></h2><h3 id="_1-geef-het-een-naam-om-het-te-temmen" tabindex="-1">1. Geef het een naam om het te temmen <a class="header-anchor" href="#_1-geef-het-een-naam-om-het-te-temmen" aria-label="Permalink to &quot;1. Geef het een naam om het te temmen&quot;">​</a></h3><p>Geef je innerlijke criticus een naam – iets ietwat belachelijks. &quot;Oh, daar gaat Negatieve Nul weer.&quot; Dit creëert afstand tussen jou en de stem, waardoor het makkelijker wordt om die te negeren.</p><h3 id="_2-betwist-het-bewijsmateriaal" tabindex="-1">2. Betwist het bewijsmateriaal <a class="header-anchor" href="#_2-betwist-het-bewijsmateriaal" aria-label="Permalink to &quot;2. Betwist het bewijsmateriaal&quot;">​</a></h3><p>Als een criticus zegt: &quot;Je presteert altijd onder druk&quot;, vraag je dan af: is dat wel echt zo? Kun je je momenten herinneren waarop je juist goed presteerde onder druk? De criticus spreekt vaak absolute termen die zelden de werkelijkheid weerspiegelen.</p><h3 id="_3-herformuleer-de-boodschap" tabindex="-1">3. Herformuleer de boodschap <a class="header-anchor" href="#_3-herformuleer-de-boodschap" aria-label="Permalink to &quot;3. Herformuleer de boodschap&quot;">​</a></h3><p>Zet kritiek om in coaching:</p><ul><li>&quot;Je gaat het missen&quot; → &quot;Concentreer je op je routine&quot;</li><li>&quot;Iedereen kijkt toe&quot; → &quot;Dit is jouw moment om te schitteren&quot;</li><li>&quot;Je faalt altijd&quot; → &quot;Je hebt al eerder met druk omgegaan&quot;</li></ul><h3 id="_4-gebruik-je-routine-van-voor-de-injectie" tabindex="-1">4. Gebruik je routine van vóór de injectie. <a class="header-anchor" href="#_4-gebruik-je-routine-van-voor-de-injectie" aria-label="Permalink to &quot;4. Gebruik je routine van vóór de injectie.&quot;">​</a></h3><p>Een degelijke voorbereiding op de opname geeft je geest iets constructiefs om zich op te concentreren, waardoor er minder ruimte overblijft voor zelfkritiek.</p><h3 id="_5-oefen-zelfcompassie" tabindex="-1">5. Oefen zelfcompassie <a class="header-anchor" href="#_5-oefen-zelfcompassie" aria-label="Permalink to &quot;5. Oefen zelfcompassie&quot;">​</a></h3><p>Behandel jezelf zoals je een teamgenoot zou behandelen. Zou je tegen een teamgenoot die het moeilijk heeft zeggen: &quot;Je bent waardeloos&quot;? Natuurlijk niet. Wees net zo vriendelijk voor jezelf.</p><h2 id="een-ondersteunende-innerlijke-stem-ontwikkelen" tabindex="-1">Een ondersteunende innerlijke stem ontwikkelen <a class="header-anchor" href="#een-ondersteunende-innerlijke-stem-ontwikkelen" aria-label="Permalink to &quot;Een ondersteunende innerlijke stem ontwikkelen&quot;">​</a></h2><p>Het doel is niet om de innerlijke criticus volledig het zwijgen op te leggen – dat is vrijwel onmogelijk. Ontwikkel in plaats daarvan een sterkere, ondersteunende stem:</p><h3 id="de-ondersteunende-stem-zegt" tabindex="-1">De ondersteunende stem zegt: <a class="header-anchor" href="#de-ondersteunende-stem-zegt" aria-label="Permalink to &quot;De ondersteunende stem zegt:&quot;">​</a></h3><ul><li>&quot;Eén worp tegelijk&quot;</li><li>&quot;Vertrouw op je training&quot;</li><li>&quot;Dit heb je al eerder gedaan.&quot;</li><li>&quot;Blijf in het nu&quot;</li><li>&quot;Adem in en kom tot rust&quot;</li></ul><h3 id="dagelijkse-oefening" tabindex="-1">Dagelijkse oefening <a class="header-anchor" href="#dagelijkse-oefening" aria-label="Permalink to &quot;Dagelijkse oefening&quot;">​</a></h3><p>Besteed elke dag 5 minuten aan:</p><ol><li>Denk terug aan een moment waarop je goed presteerde.</li><li>Onthoud hoe het in je lichaam voelde.</li><li>Luister naar wat jouw steunende stem zei.</li><li>Veranker dit gevoel met een fysieke handeling (je boule aanraken, je houding aanpassen).</li></ol><h2 id="in-competitie" tabindex="-1">In competitie <a class="header-anchor" href="#in-competitie" aria-label="Permalink to &quot;In competitie&quot;">​</a></h2><p>Wanneer de innerlijke criticus opduikt tijdens een wedstrijd:</p><ol><li><strong>Erken het</strong>: &quot;Ik merk dat ik zelfkritisch ben.&quot;</li><li><strong>Haal adem</strong>: Haal langzaam en diep adem om tot rust te komen.</li><li><strong>Gebruik je anker</strong>: Het fysieke gebaar uit je oefening</li><li><strong>Terug naar de routine</strong>: Concentreer je op je voorbereiding op de foto.</li></ol><h2 id="de-reis-op-de-lange-termijn" tabindex="-1">De reis op de lange termijn <a class="header-anchor" href="#de-reis-op-de-lange-termijn" aria-label="Permalink to &quot;De reis op de lange termijn&quot;">​</a></h2><p>Het beheersen van je innerlijke criticus is geen eenmalige oplossing. Het is een voortdurende oefening die met de tijd steeds makkelijker wordt. Topspelers elimineren zelfkritiek niet, ze leren presteren ondanks die zelfkritiek.</p><p>De innerlijke criticus zal altijd deel van je blijven uitmaken. Maar met oefening wordt zijn stem stiller en je eigen ondersteunende stem sterker. Dat is het mentale voordeel dat goede spelers van geweldige spelers onderscheidt.</p><hr><p>| <em>Gerelateerd: <a href="/en/education/mental-strength/handling-pressure">Omgaan met druk</a> | <a href="/en/education/mental-strength/pre-shot-routine">Voorbereidende routine</a> | <a href="/en/education/mindfulness/techniques">Mindfulnesstechnieken</a></em> |</p>',43)])])}]]);export{r as __pageData,a as default};
